am_broadcast_deliveries USING btree (id)"},{"name":"telegram_delivery_due_idx","valid":true,"definition":"CREATE INDEX telegram_delivery_due_idx ON public.telegram_broadcast_deliveries USING btree (status, next_attempt_at, id)"},{"name":"telegram_delivery_recipient_idx","valid":true,"definition":"CREATE UNIQUE INDEX telegram_delivery_recipient_idx ON public.telegram_broadcast_deliveries USING btree (broadcast_id, contact_id)"}],"constraints":[{"name":"telegram_broadcast_deliveries_broadcast_id_telegram_broadcasts_","type":"f","validated":true,"definition":"FOREIGN KEY (broadcast_id) REFERENCES telegram_broadcasts(id) ON DELETE CASCADE"},{"name":"telegram_broadcast_deliveries_contact_id_telegram_contacts_id_f","type":"f","validated":true,"definition":"FOREIGN KEY (contact_id) REFERENCES telegram_contacts(id) ON DELETE RESTRICT"},{"name":"telegram_broadcast_deliveries_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"telegram_delivery_status_check","type":"c","validated":true,"definition":"CHECK (((status = ANY (ARRAY[''queued''::text, ''sending''::text, ''delivered''::text, ''skipped''::text, ''failed''::text, ''unknown''::text])) AND ((attempts >= 0) AND (attempts <= 5))))"}]},"telegram_broadcasts":{"columns":[{"name":"audience","type":"jsonb","default":null,"not_null":true},{"name":"button_label","type":"text","default":null,"not_null":false},{"name":"created_at","type":"timestamp with time zone","default":"now()","not_null":true},{"name":"created_by","type":"text","default":null,"not_null":true},{"name":"event_id","type":"text","default":null,"not_null":false},{"name":"id","type":"uuid","default":"gen_random_uuid()","not_null":true},{"name":"message","type":"text","default":null,"not_null":true},{"name":"recipient_count","type":"integer","default":null,"not_null":true},{"name":"request_key","type":"uuid","default":null,"not_null":true},{"name":"status","type":"text","default":"''queued''::text","not_null":true}],"indexes":[{"name":"telegram_broadcasts_created_idx","valid":true,"definition":"CREATE INDEX telegram_broadcasts_created_idx ON public.telegram_broadcasts USING btree (created_at)"},{"name":"telegram_broadcasts_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_broadcasts_pkey ON public.telegram_broadcasts USING btree (id)"},{"name":"telegram_broadcasts_request_key_unique","valid":true,"definition":"CREATE UNIQUE INDEX telegram_broadcasts_request_key_unique ON public.telegram_broadcasts USING btree (request_key)"}],"constraints":[{"name":"telegram_broadcasts_created_by_users_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT"},{"name":"telegram_broadcasts_event_id_events_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL"},{"name":"telegram_broadcasts_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"telegram_broadcasts_request_key_unique","type":"u","validated":true,"definition":"UNIQUE (request_key)"},{"name":"telegram_broadcasts_status_check","type":"c","validated":true,"definition":"CHECK (((status = ANY (ARRAY[''queued''::text, ''completed''::text, ''cancelled''::text])) AND (recipient_count >= 0) AND ((length(message) >= 1) AND (length(message) <= 3500))))"}]},"telegram_campaigns":{"columns":[{"name":"active","type":"boolean","default":"true","not_null":true},{"name":"event_id","type":"text","default":null,"not_null":false},{"name":"key","type":"text","default":null,"not_null":true}],"indexes":[{"name":"telegram_campaigns_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_campaigns_pkey ON public.telegram_campaigns USING btree (key)"}],"constraints":[{"name":"telegram_campaigns_event_id_events_id_fk","type":"f","validated":true,"definition":"FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL"},{"name":"telegram_campaigns_key_check","type":"c","validated":true,"definition":"CHECK ((key ~ ''^[A-Za-z0-9_-]{1,64}$''::text))"},{"name":"telegram_campaigns_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (key)"}]},"telegram_updates":{"columns":[{"name":"processed_at","type":"timestamp with time zone","default":"now()","not_null":true},{"name":"update_id","type":"text","default":null,"not_null":true}],"indexes":[{"name":"telegram_updates_pkey","valid":true,"definition":"CREATE UNIQUE INDEX telegram_updates_pkey ON public.telegram_updates USING btree (update_id)"}],"constraints":[{"name":"telegram_updates_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (update_id)"}]}}'::jsonb)),
op_status AS (
 SELECT e.table_name,c.oid,c.relrowsecurity,
 c.relkind='r' AND c.relrowsecurity AND NOT row_security_active(c.oid)
 AND NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid)
 AND e.spec=jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attname) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated) ORDER BY k.conname),'[]'::jsonb) FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>'n'),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',i.indexname,'definition',i.indexdef,'valid',x.indisvalid) ORDER BY i.indexname) FROM pg_indexes i JOIN pg_namespace ns ON ns.nspname=i.schemaname JOIN pg_class ic ON ic.relnamespace=ns.oid AND ic.relname=i.indexname JOIN pg_index x ON x.indexrelid=ic.oid WHERE i.schemaname='public' AND i.tablename=e.table_name)) AS compatible
 FROM op_expected e LEFT JOIN pg_namespace n ON n.nspname='public'
 LEFT JOIN pg_class c ON c.relnamespace=n.oid AND c.relname=e.table_name
),
backend AS (SELECT oid FROM op_status UNION ALL SELECT oid FROM core_status WHERE table_name IN('community_audit','community_registration_drafts')),
security_status AS (
 SELECT (SELECT count(*) FROM backend b JOIN pg_class c ON c.oid=b.oid CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) p WHERE p.grantee=0)
 +(SELECT count(*) FROM backend b JOIN pg_attribute a ON a.attrelid=b.oid CROSS JOIN LATERAL aclexplode(a.attacl) p WHERE a.attnum>0 AND NOT a.attisdropped AND p.grantee=0)
 +(SELECT count(*) FROM backend b CROSS JOIN pg_roles r WHERE b.oid IS NOT NULL AND r.rolname IN('anon','authenticated') AND (has_table_privilege(r.oid,b.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=b.oid AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege(r.oid,b.oid,a.attnum,'SELECT,INSERT,UPDATE,REFERENCES')))) AS exposed_grants,
 (SELECT count(*) FROM backend b JOIN pg_policy p ON p.polrelid=b.oid) AS policies
),
query_index_status AS (
 SELECT v.name,c.oid,i.indisvalid AND pg_get_indexdef(c.oid)=v.definition AS compatible
 FROM (VALUES ('events_status_created_idx','CREATE INDEX events_status_created_idx ON public.events USING btree (status, created_at, id)'),('event_participants_owner_event_idx','CREATE INDEX event_participants_owner_event_idx ON public.event_participants USING btree (user_id, event_id, created_at)')) v(name,definition)
 LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||v.name) LEFT JOIN pg_index i ON i.indexrelid=c.oid
),
history_reference(lineage,position,hash,created_at) AS (VALUES ('canonical',1,'901e018c3ec116e1f701ff9ce2fe6451d9675319dd6485116f6de1118a995635',1774109638145::bigint),('canonical',2,'6d96aff4a7957e0d8dd5179b0b7eb7cc2d554a18ed0ddc0e07cb30e85a5d560c',1774123110276::bigint),('canonical',3,'444fc5920e11e0e2d5c814fbf5faa3388bd655f939496a18a55bafaf8ebd3007',1780425802302::bigint),('canonical',4,'3e22e1f7c8a7b7a92015ace31eb3146a17234fcdcc0ad252a3093f62d8b069d6',1783278410413::bigint),('canonical',5,'cef39399cddcc59ac5654848d0ccfeee1be7c3fc3b1ed531a96f55c2b75130c7',1792518180402::bigint),('canonical',6,'a09bbe7e8c4efccc1ee1b9c2641a14cc24ac460f862eaa9e72ee380bf1a19c16',1792519876795::bigint),('canonical',7,'790700b4212614d8ada5301ca937fa5716f207b256325bafdf71954ec75b65f8',1792523309776::bigint),('canonical',8,'4e0aafde81ccf079d7d03d34d6c947377ea045b3be0d9e9d6431edd38db04f1e',1792526637663::bigint),('canonical',9,'5cff7fb6291fb5eb2dac27c7c245280b1804bbed6c46f5ec8e8a127d0c67dbd8',1792572358315::bigint),('canonical',10,'68f34eb82d3bb73d79de89b059917c4eec98b2659441c172627fc2524b5444fd',1792651464393::bigint),('canonical',11,'5211f68e83569e9432e55f1c3b8e3931135415947b2060928d16dae2b9aab0eb',1792654817386::bigint),('canonical',12,'98aa3d4e9defdb995fbe1ceb0adb5988037cb3bd2722e34a4d30eb77bdb48f44',1792661261974::bigint),('canonical',13,'81ca1cd2549e4ef97e7e0889ab3e8b897f9cdfa9240c58f0e206b52ad681f47b',1792663846904::bigint),('canonical',14,'10192f05e7746ee3a4b31c5c2cf426f1b0ea325300ede6ccc1f6db6c768e0d9e',1792667918001::bigint),('legacy',1,'ad2a06696c21bd2be25083489ddaea6b792b85d4564ab48e03ba2fc512820ab9',1773604602794::bigint),('legacy',2,'ccdba012740edf96fb5bba5d6226f1a23c676f02930bd6053443e625c99ee14b',1773644876377::bigint),('legacy',3,'ba9961610e05e4e213221a998aef5b850447fd2d32478666d4fe3f29f220b98b',1773649907617::bigint),('legacy',4,'86c993f478cfcf1a3a736c03aba76a4ea514892a59fe4f3cc3dd66b277af5a89',1773652653449::bigint),('legacy',5,'8feb4711809e18ba4638998ff49d72bf870c724043ab3724af37f8028611329b',1773660780050::bigint),('legacy',6,'0a40870b155d6d7bf2febe0ab58ec870e899df0d60a442c9d1d47071e76003d2',1773661405244::bigint),('legacy',7,'396da33d8d7b10317b872f090164476b918adfe86474d4376dcdd6630c402c9a',1773661638286::bigint),('legacy',8,'8d942defd3e2b0f4cbfc6876597e042db408007db93531acf8dbf3c34d18259c',1773661753365::bigint),('legacy',9,'14965302db643c45e73a65e938256ef7e74bf33ee37bad34157263054988bcf8',1773663338060::bigint),('legacy',10,'cc30561bc6611ce8ab24ace46cdf11036d3005d845f7f9a7c76adc687e1c57c4',1773669776058::bigint),('legacy',11,'2a8d2ce25ceea6861cc4bbdae9301bd3e25f6e38901b567e467530553b89d756',1773676191563::bigint),('legacy',12,'8421e27cb69f91fcace671c11a1137ffca4630e807ea627bf3ddca21fd235a8e',1773676627166::bigint),('legacy',13,'813ff35a63d9aae4c68ebcee6c258e2f97663d77bb6d9b2cfbd281d070c6440f',1773737576251::bigint),('legacy',14,'51bbd4183b3c8de8333f4623ebed5620f9689fec0cffc7b4d5aabb4c74f8e723',1773817937324::bigint),('legacy',15,'d02cb6816076ab044127ea230e839de1b69ad2f5df08870ddcdf5e981c76466a',1773820575672::bigint),('legacy',16,'57aff6969c81e8e1b0956897ff85d9a8365bebc0e1ea8d06aa2f3180fa932e51',1773900727040::bigint),('legacy',17,'bb964e78c7212b24209139b88d9e68eab7fa3f26b9208dff191a17ab6e6e6dac',1773916312666::bigint)),
 history_object AS(SELECT to_regclass('drizzle.__drizzle_migrations') AS oid),
 history_rows AS(SELECT row_number() OVER(ORDER BY x.id) AS position,x.hash,x.created_at FROM history_object h CROSS JOIN LATERAL XMLTABLE('/*/row' PASSING CASE WHEN h.oid IS NULL THEN XMLPARSE(DOCUMENT '<empty/>') ELSE pg_catalog.table_to_xml(h.oid,false,false,'') END COLUMNS id bigint PATH 'id',hash text PATH 'hash',created_at bigint PATH 'created_at') x),
 history_state AS(SELECT count(*) AS rows,
 count(*) FILTER(WHERE EXISTS(SELECT 1 FROM history_reference r WHERE r.lineage='canonical' AND r.position=h.position AND r.created_at=h.created_at AND (r.hash=h.hash OR(r.position=5 AND h.hash='34124c4a9c89a348323b834556d45e41c7d2d2f1364c1e96e9f9a27b99f3a7bb')))) AS canonical_matches,
 count(*) FILTER(WHERE EXISTS(SELECT 1 FROM history_reference r WHERE r.lineage='legacy' AND r.position=h.position AND r.created_at=h.created_at AND r.hash=h.hash)) AS legacy_matches,
 count(*) FILTER(WHERE h.position=18 AND h.hash='10192f05e7746ee3a4b31c5c2cf426f1b0ea325300ede6ccc1f6db6c768e0d9e' AND h.created_at=1792667918001) AS legacy_markers FROM history_rows h),
 lineage AS(SELECT *,CASE WHEN rows=14 AND canonical_matches=rows THEN 'canonical-adopted'
 WHEN rows=17 AND legacy_matches=rows THEN 'legacy-ready'
 WHEN rows=18 AND legacy_matches=17 AND legacy_markers=1 THEN 'legacy-adopted'
 WHEN rows>0 AND rows<14 AND canonical_matches=rows THEN 'canonical-prefix'
 ELSE 'unknown' END AS state FROM history_state),
registration_totals AS(SELECT count(*) AS registrations,
 count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM public.users u WHERE u.id=p.user_id)) AS orphan_user_references,
 count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM public.events e WHERE e.id=p.event_id)) AS orphan_event_references,
 md5(coalesce(string_agg(to_jsonb(p)::text,'' ORDER BY p.id),'')) AS fingerprint FROM public.event_participants p),
legacy_status AS(SELECT count(*) AS users,
 count(*) FILTER(WHERE id LIKE 'tg\_%' ESCAPE '\') AS legacy_telegram_users,
 count(*) FILTER(WHERE (id LIKE 'tg\_%' ESCAPE '\' AND (NOT(id ~ '^tg_[1-9][0-9]{0,15}$' AND(length(id)<19 OR substring(id FROM 4)<='9007199254740991' COLLATE "C")) OR(telegram_chat_id IS NOT NULL AND telegram_chat_id<>substring(id FROM 4)))) OR(telegram_chat_id IS NOT NULL AND NOT(telegram_chat_id ~ '^[1-9][0-9]{0,15}$' AND(length(telegram_chat_id)<16 OR telegram_chat_id<='9007199254740991' COLLATE "C")))) AS invalid_telegram,
 count(*) FILTER(WHERE id ~ '^tg_[1-9][0-9]{0,15}$' AND email=id||'@telegram.bot') AS exact_fake_emails FROM public.users),
candidates AS(SELECT CASE WHEN id ~ '^tg_[1-9][0-9]{0,15}$' THEN substring(id FROM 4) ELSE telegram_chat_id END AS subject FROM public.users WHERE id ~ '^tg_[1-9][0-9]{0,15}$' OR telegram_chat_id IS NOT NULL),
duplicate_status AS(SELECT count(*) AS duplicate_subjects FROM(SELECT subject FROM candidates GROUP BY subject HAVING count(*)>1) d),
identity_status AS(SELECT
 (SELECT count(*) FROM telegram_contacts c LEFT JOIN user_identities i ON i.provider='telegram' AND i.provider_instance='primary' AND i.provider_user_id=c.telegram_user_id WHERE i.id IS NULL OR i.user_id<>c.user_id) AS wrong_contact_owner,
 (SELECT count(*) FROM(SELECT user_id FROM telegram_contacts GROUP BY user_id HAVING count(*) FILTER(WHERE is_primary)<>1) p) AS invalid_primary_contacts,
 (SELECT count(*) FROM telegram_miniapp_sessions s LEFT JOIN user_identities i ON i.id=s.identity_id WHERE i.id IS NULL OR i.user_id<>s.user_id OR i.provider<>'telegram' OR i.provider_instance<>'primary' OR s.token_hash !~ '^[0-9a-f]{64}$' OR s.expires_at<=s.created_at OR s.last_seen_at<s.created_at OR s.revoked_at<s.created_at) AS invalid_sessions,
 (SELECT count(*) FROM event_payment_attempts a LEFT JOIN event_participants p ON p.id=a.registration_id WHERE p.id IS NULL OR p.user_id<>a.user_id OR p.event_id<>a.event_id) AS wrong_attempt_owner,
 (SELECT count(*) FROM telegram_broadcast_deliveries d LEFT JOIN telegram_contacts c ON c.id=d.contact_id LEFT JOIN telegram_broadcasts b ON b.id=d.broadcast_id WHERE c.id IS NULL OR b.id IS NULL) AS orphan_deliveries,
 (SELECT count(*) FROM candidates c WHERE NOT EXISTS(SELECT 1 FROM telegram_contacts t WHERE t.telegram_user_id=c.subject)) AS missing_legacy_contacts,
 (SELECT count(*) FROM user_identities) AS identities,(SELECT count(*) FROM telegram_contacts) AS contacts,
 EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.user_identity_merge_log'::regclass AND tgname='user_identity_merge_log_no_mutation' AND tgenabled IN('O','A')) AS audit_guard_enabled)
SELECT jsonb_build_object('release_head','7bb5ce3b9bec0312661e3116697077eebc6cb0b2','adoption_marker_hash','10192f05e7746ee3a4b31c5c2cf426f1b0ea325300ede6ccc1f6db6c768e0d9e',
 'transaction_read_only',current_setting('transaction_read_only'),'postgres_version',current_setting('server_version_num'),
 'lineage',l.state,'ledger',jsonb_build_object('rows',l.rows,'legacy_matches',l.legacy_matches,'canonical_matches',l.canonical_matches,'legacy_markers',l.legacy_markers),
 'core_schema',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'compatible',coalesce(compatible,false)) ORDER BY table_name) FROM core_status),
 'release_schema',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'status',CASE WHEN oid IS NULL THEN 'NOT_PRESENT' WHEN compatible THEN 'COMPATIBLE' ELSE 'BLOCKER' END) ORDER BY table_name) FROM op_status),
 'query_indexes',(SELECT jsonb_agg(jsonb_build_object('name',name,'status',CASE WHEN oid IS NULL THEN 'NOT_PRESENT' WHEN compatible THEN 'COMPATIBLE' ELSE 'BLOCKER' END) ORDER BY name) FROM query_index_status),
 'security',jsonb_build_object('exposed_grants',s.exposed_grants,'policies',s.policies),
 'legacy',jsonb_build_object('users',u.users,'legacy_telegram_users',u.legacy_telegram_users,'invalid_telegram',u.invalid_telegram,'exact_fake_emails',u.exact_fake_emails,'duplicate_subjects',d.duplicate_subjects),
 'registration_baseline',jsonb_build_object('registrations',r.registrations,'orphan_user_references',r.orphan_user_references,'orphan_event_references',r.orphan_event_references,'fingerprint',r.fingerprint),
 'identity_integrity',jsonb_build_object('wrong_contact_owner',i.wrong_contact_owner,'invalid_primary_contacts',i.invalid_primary_contacts,'invalid_sessions',i.invalid_sessions,'wrong_attempt_owner',i.wrong_attempt_owner,'orphan_deliveries',i.orphan_deliveries,'missing_legacy_contacts',i.missing_legacy_contacts,'identities',i.identities,'contacts',i.contacts,'audit_guard_enabled',i.audit_guard_enabled),
 'production_registration_baseline_matches',(r.registrations=43 AND r.fingerprint='f599ce780eed5cf293d9838316eb9f54'),
 'assessment',CASE WHEN NOT EXISTS(SELECT 1 FROM core_status WHERE compatible IS DISTINCT FROM true) AND s.exposed_grants=0 AND s.policies=0 AND r.orphan_user_references=0 AND r.orphan_event_references=0
 AND NOT EXISTS(SELECT 1 FROM op_status WHERE compatible IS DISTINCT FROM true)
 AND NOT EXISTS(SELECT 1 FROM query_index_status WHERE compatible IS DISTINCT FROM true)
 AND i.wrong_contact_owner=0 AND i.invalid_primary_contacts=0 AND i.invalid_sessions=0 AND i.wrong_attempt_owner=0 AND i.orphan_deliveries=0 AND i.missing_legacy_contacts=0 AND i.audit_guard_enabled AND u.exact_fake_emails=0
 AND (l.state='canonical-adopted' OR(l.state='legacy-adopted' AND r.registrations=43 AND r.fingerprint='f599ce780eed5cf293d9838316eb9f54'))
 THEN 'PASS' ELSE 'BLOCKER' END) AS postcheck
 FROM lineage l CROSS JOIN security_status s CROSS JOIN registration_totals r CROSS JOIN legacy_status u CROSS JOIN duplicate_status d CROSS JOIN identity_status i;
COMMIT;
